    // Explicit isolated fixture; production actions, real prefab nodes and real terrain are exercised.
    public static class ExplorationUtilityQa
    {
        public static string Phase{get;private set;}="idle";
        private static string Root=>Path.GetFullPath("Captures/exploration-utility-expansion");
        private static WorldSaveService save;private static PlayerInventory bag;private static WorldGenerator world;private static ContentCatalog catalog;private static PlayerExplorationUtility utility;private static NetworkSession host;private static NetworkPlayer actor;
        private static void Log(string text){Directory.CreateDirectory(Root);File.AppendAllText(Root+"/live.tsv",DateTime.UtcNow.ToString("O")+"\t"+Phase+"\t"+text+"\n");}
        private static void Check(bool value,string text){Log((value ? "PASS " : "FAIL ")+text);if(!value)throw new InvalidOperationException(text);}
        private static void Step(string text){Phase=text;Log("begin");}
        private static IEnumerator Guard(IEnumerator flow)
        {var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object value;try{more=stack.Peek().MoveNext();value=more ? stack.Peek().Current : null;}catch(Exception e){Phase="failed";Log(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(value is IEnumerator child)stack.Push(child);else yield return value;}Phase="complete";Log("complete");}
        private static IEnumerator Capture(string name){if(Application.isBatchMode)yield break;yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Root+"/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        private static void Select(string id)
        {var item=catalog.Item(id);if(bag.Model.CountItem(item)==0)bag.Model.Add(item,1);var slot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==item);if(slot>=9){bag.Model.MoveStack(slot,bag.SelectedIndex);slot=bag.SelectedIndex;}bag.SelectSlot(slot);}
        private static void Move(Vector2 p){bag.GetComponent<PlayerInputCommands>().Session.CloseInventory();bag.GetComponent<PlayerInputCommands>().SetMove(Vector2.zero);bag.transform.position=p;bag.GetComponent<Rigidbody2D>().position=p;bag.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();world.Chunks.Reconcile();world.Chunks.DrainPending();NetworkCreatureWorld.Active?.FlushPending();}
        private static void Clear(Vector2 p,float radius=19){foreach(var r in UnityEngine.Object.FindObjectsByType<ResourceNode>(FindObjectsSortMode.None))if(Vector2.Distance(r.transform.position,p)<radius)r.gameObject.SetActive(false);Physics2D.SyncTransforms();}
        private static ResourceNode Ore(Vector2 p)
        {var rule=Array.FindIndex(world.Definition.Resources,r=>r.Family==ResourceFamily.Mineral && r.Prefab.Definition.DropItem.Id=="iron_ore");Check(rule>=0,"existing Iron rule");return world.CreateResource("qa-survey-"+Guid.NewGuid().ToString("N"),rule,p,1);}
        public static void Begin()
        {ContentExpansionQa.Prepare();save=ContentExpansionQa.S;bag=save.Player;world=save.World;catalog=save.Catalog;utility=bag.GetComponent<PlayerExplorationUtility>();world.Animals.enabled=world.Renewal.enabled=false;Application.runInBackground=true;Phase="starting";save.StartCoroutine(Guard(Single()));}
        private static IEnumerator Survey(SurveyPhase phase,string label)
        {utility.ResetTransient();Select("ore_surveyor");var queries=utility.QueryCount;var active=world.Chunks.ActiveCount;var pending=world.Chunks.PendingCount;var presentation=world.Chunks.PresentationOnlyCount;Check(bag.GetComponent<PlayerInputCommands>().Attack(),"primary starts "+label);Check(!utility.Use(),"same-frame duplicate rejected");yield return new WaitForSecondsRealtime(1.5f);Check(utility.Survey.Phase==phase,label+" result="+utility.Survey.Phase);Check(utility.QueryCount==queries+1,"one query on completion");Check(active==world.Chunks.ActiveCount && pending==world.Chunks.PendingCount && presentation==world.Chunks.PresentationOnlyCount,"no chunk/simulation/presentation increase");Check(!utility.Use(),"cooldown enforced");Log("bounded colliders="+utility.LastColliderCount+" query_ms="+utility.LastQueryMilliseconds.ToString("F4"));yield return Capture(label);}
        private static IEnumerator Single()
        {
            L.SetLanguage("ko");Step("craft-inventory");Move(Vector2.zero);Clear(Vector2.zero);bag.Model.Restore(new InventoryModel(36).Capture(),catalog);ContentExpansionQa.Bench=null;ContentExpansionQa.OpenBench();var craft=bag.GetComponent<PlayerCrafting>();craft.SetSelected(catalog.Recipe("signal_whistle"));yield return null;Check(ContentExpansionQa.Craft("signal_whistle")==1,"WBI actual card Wood2+Fiber2");yield return Capture("01-whistle-recipe");ContentExpansionQa.OpenBench(2);craft.SetSelected(catalog.Recipe("ore_surveyor"));yield return null;Check(ContentExpansionQa.Craft("ore_surveyor")==1,"WBII actual card Wood2+Bronze2+Leather1");yield return Capture("02-surveyor-recipe");craft.CloseCrafting();
            Step("baseline-navigation-light");Select("compass");var navigation=bag.GetComponent<PlayerNavigation>();Check(navigation.AssignHome(ContentExpansionQa.Bench),"Compass Home assigned");Check(navigation.HasCompass && navigation.TryHome(world,out _),"Compass Home bearing available");yield return Capture("03-compass");
            var beacon=ContentExpansionQa.Place("signal_beacon",new Vector2(-5,2));navigation.SelectNavigation(NavigationMode.Beacon,beacon.SaveId);Check(navigation.TryBeacon(out var bp,out _) && bp==(Vector2)beacon.transform.position,"persistent Beacon selected");yield return Capture("04-beacon");
            Select("telescope");var wanted=world.Chunks.WantedCount;Check(bag.GetComponent<PlayerPrimaryAction>().TryUse(),"Telescope primary");bag.GetComponent<PlayerTelescope>().Aim(Vector2.up);yield return new WaitForSecondsRealtime(.8f);Check(world.Chunks.WantedCount==wanted && world.Chunks.PresentationOnlyCount>0,"Telescope terrain-only presentation");yield return Capture("05-telescope");bag.GetComponent<PlayerTelescope>().Exit();yield return new WaitForSecondsRealtime(3.3f);
            var cave=world.Map.Continental.Caves[0];Move(cave.Rooms.OrderByDescending(r=>r.Depth).First().Center);Clear(bag.transform.position);Select("torch");yield return null;Check(bag.GetComponent<PlayerLightSource>().Mount==PlayerLightMount.Held,"Torch held");yield return Capture("06-torch-cave");
            Select("lantern");Check(bag.GetComponent<PlayerPrimaryAction>().TryUse(),"Lantern equip");Select("ore_surveyor");yield return null;Check(bag.GetComponent<PlayerLightSource>().Gameplay.Definition.Radius==8.5f,"Lantern hands free radius8.5");yield return Capture("07-lantern-cave");Select("crystal_lantern");Check(bag.GetComponent<PlayerPrimaryAction>().TryUse(),"Crystal Lantern equip");Select("ore_surveyor");yield return null;Check(Mathf.Abs(bag.GetComponent<PlayerLightSource>().Gameplay.Definition.Radius-11.475f)<.01f,"Crystal Lantern radius11.475");yield return Capture("08-crystal-cave");
            Step("pan-water");var tin=world.Map.Continental.GuaranteedResources.First(r=>world.Definition.Resources[r.Rule].Prefab.Definition.HarvestMethod==HarvestMethod.Panning);Move(tin.Position+Vector2.down*1.4f);Select("prospecting_pan");var node=UnityEngine.Object.FindObjectsByType<ResourceIdentity>(FindObjectsSortMode.None).First(r=>r.Id==tin.Id).Node;var hp=node.Health.Current;Check(node.Harvest(catalog.Item("prospecting_pan").Tool,25,bag)>0 && node.Health.Current<hp,"Pan physically harvests Tin, no radar");yield return Capture("09-pan");
            for(var y=517;y<3000;y+=17){var p=new Vector2(world.Map.RiverAt(y)+7,y);if(!world.Map.IsWalkable(p,0))continue;Move(p);Select("waterskin");if(bag.GetComponent<PlayerWaterskin>().Fill())break;}Check(bag.SelectedStack.Charges==3,"Waterskin refill natural water");bag.GetComponent<PlayerSurvival>().Model.SetMeters(20,20);Check(bag.GetComponent<PlayerWaterskin>().Drink() && bag.SelectedStack.Charges==2,"Waterskin drink charge");yield return Capture("10-waterskin");
            Step("survey-local");Move(Vector2.zero);Clear(Vector2.zero);var ore=Ore(new Vector2(-8,0));Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Empty,"11-no-proper-tool");Select("diamond_pickaxe");yield return Survey(SurveyPhase.Found,"12-local-ore");Check(catalog.Items[utility.Survey.Item].Id=="iron_ore" && utility.Survey.Bearing==4,"coarse west Iron only, no coords");
            var wall=ContentExpansionQa.Place("wood_wall",new Vector2(-4,0));Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Empty,"13-wall-blocked");wall.gameObject.SetActive(false);ore.gameObject.SetActive(false);Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Empty,"14-no-ore");
            Step("survey-cave-boundary");Move(cave.Rooms[0].Center);Clear(bag.transform.position);ore=Ore((Vector2)bag.transform.position+Vector2.left*3);Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Found,"15-cave");ore.gameObject.SetActive(false);Move(new Vector2(63,0));Clear(bag.transform.position);ore=Ore(new Vector2(66,0));Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Found,"16-chunk-boundary");ore.gameObject.SetActive(false);
            // No generation call: move only the fixture body to an inactive region, leaving scheduler disabled.
            world.Chunks.enabled=false;var old=bag.transform.position;bag.transform.position=new Vector2(21000,21000);bag.GetComponent<Rigidbody2D>().position=bag.transform.position;Physics2D.SyncTransforms();yield return Survey(SurveyPhase.Empty,"17-ungenerated");bag.transform.position=old;bag.GetComponent<Rigidbody2D>().position=old;world.Chunks.enabled=true;
            Step("survey-cancel-repeat");Move(Vector2.zero);Clear(Vector2.zero);Select("ore_surveyor");utility.ResetTransient();Check(utility.Use(),"start movement cancel");bag.GetComponent<PlayerInputCommands>().SetMove(Vector2.up);yield return new WaitForSecondsRealtime(.2f);Check(utility.Survey.Phase==SurveyPhase.Cancelled,"input movement cancels");bag.GetComponent<PlayerInputCommands>().SetMove(Vector2.zero);
            foreach(var cause in new[]{"damage","modal","switch"}){utility.ResetTransient();Select("ore_surveyor");Check(utility.Use(),"start "+cause);if(cause=="damage")bag.GetComponent<Health>().ApplyDamage(1,true);else if(cause=="modal")world.Session.OpenInventory();else Select("compass");yield return new WaitForSecondsRealtime(.2f);Check(utility.Survey.Phase==SurveyPhase.Cancelled,cause+" cancels without query");world.Session.CloseInventory();}
            utility.ResetTransient();Select("ore_surveyor");var before=utility.QueryCount;Check(utility.Use(),"real cooldown start");yield return new WaitForSecondsRealtime(1.5f);Check(!utility.Use(),"early repeat denied");yield return new WaitForSecondsRealtime(10.7f);Check(utility.Use(),"repeat accepted after12 seconds");yield return new WaitForSecondsRealtime(1.5f);Check(utility.QueryCount==before+2,"exact two completed queries across cooldown");
            Step("signal-save-load");Select("signal_whistle");Check(bag.GetComponent<PlayerInputCommands>().Attack() && !utility.Use(),"SP signal primary and spam reject");yield return Capture("18-signal-sent");Check(save.Save(),"isolated Save11");save.Apply(save.Repository.Read(save.Validate));Check(true,"isolated saved snapshot Apply11");world.Chunks.DrainPending();yield return null;Check(utility.Signal.Until==0 && utility.Survey.Phase==SurveyPhase.None,"Load discards transient signal/survey");Check(bag.Model.CountItem(catalog.Item("ore_surveyor"))==1 && bag.Model.CountItem(catalog.Item("signal_whistle"))==1,"new item stacks persist");yield return Capture("19-load");
            Select("ore_surveyor");Check(utility.Use(),"start before death");bag.GetComponent<Health>().ApplyDamage(10000,true);yield return new WaitForSecondsRealtime(.2f);Check(utility.Survey.Phase==SurveyPhase.Cancelled && !utility.Use(),"death cancels and denies use");
        }
        public static void BeginHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated profile required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/host/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;Phase="starting";host.StartCoroutine(Guard(HostFlow()));}
        public static void BeginCoopHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated profile required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/coop/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;host.StartCoroutine(Guard(CoopHost()));}
        public static void BeginCoopClient()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated profile required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.ProfileOverride=Guid.NewGuid().ToString("N");host.StartCoroutine(Guard(CoopClient()));}
        private static void CoopTransport(){Application.runInBackground=true;}
        private static IEnumerator CoopHost()
        {
            Step("coop-host-wait");CoopTransport();yield return EnterHost();Move(new Vector2(10,0));Clear(Vector2.zero,25);var until=Time.realtimeSinceStartup+150;NetworkPlayer peer=null;
            while(Time.realtimeSinceStartup<until){peer=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject && !p.IsOwner);if(peer!=null)break;yield return null;}Check(peer!=null,"real LAN client joined separate process");
            peer.Motor.enabled=false;var remote=peer.GetComponent<PlayerInventory>();remote.transform.position=Vector2.zero;remote.GetComponent<Rigidbody2D>().position=Vector2.zero;foreach(var id in new[]{"ore_surveyor","signal_whistle","diamond_pickaxe"})remote.Model.Add(catalog.Item(id),1);world.Chunks.Reconcile();world.Chunks.DrainPending();Ore(new Vector2(-8,0));NetworkCreatureWorld.Active.FlushPending();Physics2D.SyncTransforms();Select("signal_whistle");Check(utility.Use(),"Host sends signal for real Client");
            Step("coop-host-requests");until=Time.realtimeSinceStartup+50;var ru=peer.GetComponent<PlayerExplorationUtility>();while(Time.realtimeSinceStartup<until && (ru.QueryCount==0 || ru.Signal.Until<=ru.Now))yield return null;
            Check(ru.QueryCount==1 && ru.Survey.Phase==SurveyPhase.Found,"real Client request caused exactly one Host query");Check(ru.Signal.Until>ru.Now && Vector2.Distance(ru.Signal.Point,Vector2.zero)<.2f,"real Client signal location chosen by Host");Check(utility.TryPeerSignal(out var point) && Vector2.Distance(point,Vector2.zero)<.2f,"Host receives Client signal");yield return new WaitForSecondsRealtime(.25f);var hud=UnityEngine.Object.FindFirstObjectByType<NavigationHud>();Check(hud.Destination.text==L.Text("ui.signal.peer"),"Host navigation HUD shows real Client signal after display tick");yield return Capture("23-real-client-signal");until=Time.realtimeSinceStartup+30;while(Time.realtimeSinceStartup<until && peer!=null && peer.IsSpawned)yield return null;Check(peer==null || !peer.IsSpawned,"real client disconnect despawns marker owner");Check(!utility.TryPeerSignal(out _),"real client disconnect removes HUD target");
        }
        private static IEnumerator CoopClient()
        {
            Step("coop-client-join");CoopTransport();var task=host.Join(ConnectionRoute.LocalNetwork,"127.0.0.1");yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"Client transport started");var until=Time.realtimeSinceStartup+45;NetworkPlayer local=null;
            var nextLog=0f;while(Time.realtimeSinceStartup<until){if(Time.realtimeSinceStartup>=nextLog){nextLog=Time.realtimeSinceStartup+2;Log("join diagnostic state="+host.State+" approved="+host.Manager.IsApproved+" connected="+host.Manager.IsConnectedClient+" message="+host.MessageKey+" reason="+host.Manager.DisconnectReason);}local=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.IsOwner && p.NetworkObject.IsPlayerObject);if(local!=null && local.GetComponent<PlayerInventory>().Model.CountItem(Resources.Load<SaveGameRules>("SaveGameRules").Catalog.Item("signal_whistle"))>0)break;yield return null;}Check(local!=null,"Client owner spawned");bag=local.GetComponent<PlayerInventory>();catalog=Resources.Load<SaveGameRules>("SaveGameRules").Catalog;utility=bag.GetComponent<PlayerExplorationUtility>();local.GetComponent<PlayerInputAdapter>().enabled=false;world=NetworkCreatureWorld.Active.World;
            var slot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==catalog.Item("ore_surveyor"));bag.SelectSlot(slot);yield return new WaitForSecondsRealtime(.7f);Check(local.Commands.Attack(),"Client Primary request survey");until=Time.realtimeSinceStartup+8;while(Time.realtimeSinceStartup<until && utility.Survey.Phase!=SurveyPhase.Found)yield return null;Check(utility.Survey.Phase==SurveyPhase.Found && utility.QueryCount==0,"Client receives Host result without any local resource query");
            Check(utility.TryPeerSignal(out var point) && Vector2.Distance(point,new Vector2(10,0))<.2f,"Client receives Host temporary signal");slot=Enumerable.Range(0,bag.Model.Capacity).First(i=>bag.Model.GetSlot(i).Item==catalog.Item("signal_whistle"));bag.SelectSlot(slot);yield return new WaitForSecondsRealtime(.7f);Check(local.Commands.Attack(),"Client Primary request signal");yield return new WaitForSecondsRealtime(.7f);var signal=utility.Signal;Check(signal.Until>utility.Now,"Client receives own server-confirmed signal");local.Commands.Attack();yield return new WaitForSecondsRealtime(.7f);Check(utility.Signal.Equals(signal),"duplicate Client request does not extend signal");yield return new WaitForSecondsRealtime(1);host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);
        }
        private static IEnumerator EnterHost()
        {var task=host.Host(ConnectionRoute.LocalNetwork);yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"Local Host "+host.LastFailure);Check(host.EnterGame(),"enter Host");var until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){actor=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned&&p.NetworkObject.IsPlayerObject);if(actor!=null&&NetworkCreatureWorld.Active!=null&&NetworkCreatureWorld.Active.Ready)break;yield return null;}Check(actor!=null&&NetworkCreatureWorld.Active.Ready,"Host ready");bag=actor.GetComponent<PlayerInventory>();world=NetworkCreatureWorld.Active.World;catalog=NetworkCreatureWorld.Active.Catalog;utility=bag.GetComponent<PlayerExplorationUtility>();actor.Motor.enabled=actor.GetComponent<PlayerInputAdapter>().enabled=false;var w=NetworkCreatureWorld.Active;w.Clock.enabled=w.Animals.enabled=w.Goblins.enabled=w.Night.enabled=world.Renewal.enabled=false;yield return null;}
        private static IEnumerator HostFlow()
        {
            Step("host-survey");yield return EnterHost();Move(Vector2.zero);Clear(Vector2.zero);Select("diamond_pickaxe");Select("ore_surveyor");Ore(new Vector2(-8,0));Physics2D.SyncTransforms();Check(actor.ExecutePrimary(1),"Host authoritative survey request");Check(!actor.ExecutePrimary(1),"duplicate sequence rejected");yield return new WaitForSecondsRealtime(1.5f);var net=actor.GetComponent<NetworkExplorationUtility>();Check(net.Survey.Value.Phase==SurveyPhase.Found,"server publishes owner-only coarse result");yield return Capture("20-host-survey");
            Step("host-signals");Select("signal_whistle");Check(actor.ExecutePrimary(2) && !actor.ExecutePrimary(2) && !actor.ExecutePrimary(3),"Host signal accepted once; serial and cooldown reject spam");Check(net.Signal.Value.Until>utility.Now,"server signal replicated");
            var peers=new List<NetworkPlayer>();for(var i=0;i<3;i++){var p=UnityEngine.Object.Instantiate(host.PlayerPrefab,new Vector2(10+i*5,0),Quaternion.identity).GetComponent<NetworkPlayer>();p.NetworkObject.Spawn();p.Motor.enabled=p.GetComponent<PlayerInputAdapter>().enabled=false;peers.Add(p);}
            yield return null;foreach(var p in peers){bag=p.GetComponent<PlayerInventory>();utility=bag.GetComponent<PlayerExplorationUtility>();Check(utility.TryPeerSignal(out var point),"simulated receiver sees latest eligible signal");Select("signal_whistle");Check(p.ExecutePrimary(1),"simulated peer accepted signal");Check(!p.ExecutePrimary(2),"simulated peer spam denied");yield return new WaitForSecondsRealtime(.1f);}
            bag=actor.GetComponent<PlayerInventory>();utility=bag.GetComponent<PlayerExplorationUtility>();Check(NetworkPlayer.Active.Count(p=>p.IsSpawned && p.GetComponent<PlayerExplorationUtility>().Signal.Until>utility.Now)==4,"at most four sender signals");Check(utility.TryPeerSignal(out var latest) && latest==(Vector2)peers[2].transform.position,"receiver selects only newest eligible signal");peers[2].NetworkObject.Despawn();Check(utility.TryPeerSignal(out latest) && latest==(Vector2)peers[1].transform.position,"disconnect removes sender immediately");
            Move(new Vector2(150,0));Check(!utility.TryPeerSignal(out _),"out of range signal hidden");Move(world.Map.Continental.Caves[0].Rooms[0].Center);Check(!utility.TryPeerSignal(out _),"surface signal hidden in cave");Move(Vector2.zero);yield return Capture("21-host-signals");yield return new WaitForSecondsRealtime(20.2f);Check(!utility.TryPeerSignal(out _) && utility.Signal.Until==0,"Host expiry clears all signals");foreach(var p in peers)if(p!=null && p.IsSpawned)p.NetworkObject.Despawn();
            Step("host-rehost");utility.ResetTransient();Select("signal_whistle");Check(actor.ExecutePrimary(4),"signal before save");Select("ore_surveyor");Check(actor.ExecutePrimary(5),"channel before save");Check(host.TrySaveWorld(),"Host Save11");host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);yield return new WaitForSecondsRealtime(.3f);yield return EnterHost();Check(utility.Signal.Until==0 && utility.Survey.Phase==SurveyPhase.None,"reHost no transient ping/channel");Check(bag.Model.CountItem(catalog.Item("ore_surveyor"))==1 && bag.Model.CountItem(catalog.Item("signal_whistle"))==1,"reHost new inventory retained");yield return Capture("22-rehost");
        }
    }
}
